(async () => {
  const pages = figma.root.children;
  const result = {};

  for (const page of pages) {
    await page.loadAsync();
    const textNodes = page.findAll(n => n.type === 'TEXT');
    result[page.name] = {
      id: page.id,
      textCount: textNodes.length,
      texts: textNodes.map(t => ({ id: t.id, name: t.name, characters: t.characters })).slice(0, 100),
      children: page.children.map(c => ({ id: c.id, name: c.name, type: c.type, x: c.x, y: c.y, width: c.width, height: c.height }))
    };
  }

  return JSON.stringify(result, null, 2);
})();

