arguments.code:
(async () => {
  const pages = figma.root.children;
  const compPage = pages.find(p => p.name.includes('Components'));
  const mediaPage = pages.find(p => p.name.includes('Media'));
  const foundPage = pages.find(p => p.name.includes('Foundations'));

  await compPage.loadAsync();
  await mediaPage.loadAsync();
  await foundPage.loadAsync();

  const getNodesInfo = (page) => {
    return page.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      x: c.x, y: c.y, width: c.width, height: c.height,
      childrenCount: c.children ? c.children.length : 0,
      children: c.children ? c.children.map(ch => ({ id: ch.id, name: ch.name, type: ch.type })) : []
    }));
  };

  return JSON.stringify({
    components: getNodesInfo(compPage),
    media: getNodesInfo(mediaPage)
  }, null, 2);
})();

